// El panel envía { tool, batch }. `batch` sube en cada "Recargar desde n8n",
// así que sirve para devolver una tanda distinta.
// Sustituye esta lista por una llamada a tu modelo (nodo OpenAI, Anthropic, etc.).
const { batch = 0 } = $input.first().json.body ?? {};

const tandas = [
  [
    { text: 'Cobré $50K sin una sola llamada de ventas. Así lo hice:', metric: '78%' },
    { text: 'Tu oferta no es cara. Tu oferta no se entiende.', metric: '71%' },
    { text: 'Dejé de publicar todos los días y crecí el triple.', metric: '69%' },
    { text: 'El error de los $10K que casi cierra mi agencia.', metric: '64%' },
  ],
  [
    { text: '3 frases que suben tu ticket un 40% en la misma llamada.', metric: '74%' },
    { text: 'Si tu DM empieza así, ya perdiste la venta.', metric: '70%' },
    { text: 'Nadie compra tu servicio. Compran no tener el problema.', metric: '67%' },
    { text: 'Lo que un cliente de $30K me dijo al rechazarme.', metric: '62%' },
  ],
  [
    { text: 'Mi agenda de 4 horas semanales factura más que mi equipo de 6.', metric: '76%' },
    { text: 'El contenido que menos me gustó publicar trajo 12 clientes.', metric: '68%' },
    { text: 'Deja de vender resultados. Vende la decisión.', metric: '65%' },
    { text: 'Cómo cobrar por adelantado sin sonar desesperado.', metric: '61%' },
  ],
];

return tandas[batch % tandas.length].map((json) => ({ json }));
